/* Phase 1: hero scroll animation only. Theme tokens and fonts arrive in phase 2. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

:root {
  --ground: #1F1A18; /* the footage's own background, so the frame's edges disappear */
  color-scheme: dark;
}

html,
body {
  margin: 0;
  background: var(--ground);
}

/* A tall section; the stage inside it stays pinned while it scrolls past. */
.hero {
  position: relative;
  height: var(--hero-length, 400vh);
}

.stage {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh; /* the book stays whole behind mobile browser bars */
  overflow: hidden;
}

.stage canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* Reduced motion: no scrubbing, just the open book. */
.still .hero {
  height: auto;
}

/* Try-out panel: localhost only, removed before launch. */
.try {
  position: fixed;
  left: 16px;
  bottom: 16px;
  z-index: 10;
  max-width: calc(100vw - 32px);
  padding: 10px 12px;
  font: 13px/1.3 system-ui, sans-serif;
  color: #E7E5E4;
  background: rgba(12, 10, 9, 0.88);
  border: 1px solid #3F3A37;
  border-radius: 10px;
}

.try summary {
  cursor: pointer;
  color: #FAFAF9;
}

.try summary small {
  color: #A8A29E;
}

.try-row {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
}

.try-row span {
  flex: 0 0 76px;
  color: #A8A29E;
}

.try button {
  min-height: 32px;
  padding: 0 10px;
  font: inherit;
  color: inherit;
  background: transparent;
  border: 1px solid #3F3A37;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
}

.try button:hover {
  border-color: #78716C;
}

.try button[aria-pressed="true"] {
  color: #1C1917;
  background: #D4AF37;
  border-color: #D4AF37;
}

.try summary:focus-visible,
.try button:focus-visible {
  outline: 2px solid #D4AF37;
  outline-offset: 2px;
}

@media (pointer: coarse) {
  .try button {
    min-height: 44px;
  }
}

