// Phase 1: the hero scroll animation.
// Retouched video frames of the Qur'an opening, drawn to a canvas by scroll position.
// Spec: WEBSITE-BUILD.md sections 2 and 3.

(() => {
  const clamp = (v) => Math.min(1, Math.max(0, v));

  // Frames --------------------------------------------------------------------

  const SKIP = [39, 40]; // identical to f038, a hold in the source video
  const urls = [];
  for (let i = 0; i <= 88; i++) {
    if (!SKIP.includes(i)) urls.push(`assets/hero/frames/f${String(i).padStart(3, '0')}.png`);
  }
  const LAST = urls.length - 1; // 87 frames, indices 0..86

  // Geometry, in pixels of the 1280x720 frames ----------------------------------

  const SRC_W = 1280;
  const SRC_H = 720;
  const BOOK_LEFT = 255;   // left edge of the book; it never moves in the footage
  const BOOK_H = 580;      // y 70-650, centred on the frame's middle
  const SPINE = 640;       // right edge until the cover passes upright
  const OPEN_RIGHT = 1037; // right edge fully open
  const FEATHER_X = 180;   // how far the frame's rectangle fades into the stage
  const FEATHER_Y = 40;

  // Timeline, as a share of the hero's scroll ------------------------------------

  const OPEN_START = 0.1;
  const OPEN_END = 0.6;
  const HERO_LENGTH = { slow: '550vh', normal: '400vh', quick: '300vh' };

  // Settings: the defaults are what ships; the try-out panel changes them locally.

  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
  const settings = { size: 'sharp', phone: 'zoom', speed: 'normal', motion: null }; // motion null: follow the system
  try {
    Object.assign(settings, JSON.parse(localStorage.getItem('hero-try')));
  } catch {}
  const still = () => (settings.motion ? settings.motion === 'off' : reduceMotion.matches);

  const hero = document.querySelector('.hero');
  const stage = hero.querySelector('.stage');
  const canvas = stage.querySelector('canvas');
  const ctx = canvas.getContext('2d');

  const frames = []; // decoded images by index, filled in as they arrive
  const rights = []; // measured right edge of the book in each frame
  const started = new Set();

  let shown = -1;
  let dirty = true;
  let queued = false;
  let visible = true;

  // Loading -----------------------------------------------------------------------

  function load(i) {
    if (started.has(i)) return;
    started.add(i);
    const img = new Image();
    img.src = urls[i];
    img.decode().then(
      () => {
        frames[i] = img;
        rights[i] = measureRight(img);
        schedule();
      },
      () => console.warn(`Frame missing: ${urls[i]}`), // the nearest loaded frame is drawn instead
    );
  }

  // First and last frames, then coarse to fine, so scrubbing works before everything arrives.
  function loadAll() {
    load(0);
    load(LAST);
    for (const step of [8, 4, 2, 1]) {
      for (let i = 0; i <= LAST; i += step) load(i);
    }
  }

  // Once the cover passes upright its cream lining faces the camera, so the book's right
  // edge is the rightmost bright pixel along the middle row, and never less than the spine.
  const probe = document.createElement('canvas');
  probe.width = SRC_W;
  probe.height = 1;
  const probeCtx = probe.getContext('2d', { willReadFrequently: true });

  function measureRight(img) {
    try {
      probeCtx.drawImage(img, 0, SRC_H / 2, SRC_W, 1, 0, 0, SRC_W, 1);
      const px = probeCtx.getImageData(0, 0, SRC_W, 1).data;
      for (let x = SRC_W - 1; x > SPINE; x--) {
        if (px[x * 4] + px[x * 4 + 1] + px[x * 4 + 2] > 300) return x + 1;
      }
      return SPINE;
    } catch {
      return null; // pixels unreadable, e.g. opened as a file rather than through serve.js
    }
  }

  // Averaged over nearby frames so the framing glides instead of stepping.
  function rightEdge(i) {
    let sum = 0;
    let n = 0;
    for (let j = Math.max(0, i - 3); j <= Math.min(LAST, i + 3); j++) {
      if (rights[j] != null) {
        sum += rights[j];
        n++;
      }
    }
    return n ? sum / n : SPINE + ((OPEN_RIGHT - SPINE) * i) / LAST;
  }

  // Drawing -----------------------------------------------------------------------

  // Scale and horizontal centre for frame i. The book is centred by choosing which part
  // of the frame is drawn, never by moving the canvas.
  function framing(i, width, height) {
    const right = rightEdge(i);
    const bookW = (settings.phone === 'zoom' ? right : OPEN_RIGHT) - BOOK_LEFT;
    let scale = Math.min((height * 0.8) / BOOK_H, (width * 0.88) / bookW);
    if (settings.size === 'sharp') scale = Math.min(scale, 1); // never stretch the 720p footage
    return { scale, centre: (BOOK_LEFT + right) / 2 };
  }

  function draw(i) {
    const width = canvas.clientWidth;
    const height = canvas.clientHeight;
    const { scale, centre } = framing(i, width, height);
    const w = SRC_W * scale;
    const h = SRC_H * scale;
    const x = width / 2 - centre * scale;
    const y = (height - h) / 2;

    ctx.globalCompositeOperation = 'source-over';
    ctx.clearRect(0, 0, width, height);
    ctx.drawImage(frames[i], x, y, w, h);

    // Fade the frame's rectangle out at its edges so it never shows against the stage.
    ctx.globalCompositeOperation = 'destination-in';
    ctx.fillStyle = feather(ctx.createLinearGradient(x, 0, x + w, 0), FEATHER_X / SRC_W);
    ctx.fillRect(x, y, w, h);
    ctx.fillStyle = feather(ctx.createLinearGradient(0, y, 0, y + h), FEATHER_Y / SRC_H);
    ctx.fillRect(x, y, w, h);
    ctx.globalCompositeOperation = 'source-over';
  }

  function feather(gradient, edge) {
    gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
    gradient.addColorStop(edge, '#000');
    gradient.addColorStop(1 - edge, '#000');
    gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
    return gradient;
  }

  function targetFrame() {
    if (still()) return LAST;
    const range = hero.offsetHeight - stage.offsetHeight;
    const p = range > 0 ? clamp(-hero.getBoundingClientRect().top / range) : 0;
    const t = clamp((p - OPEN_START) / (OPEN_END - OPEN_START));
    return Math.round(t * t * (3 - 2 * t) * LAST); // smoothstep: eases into and out of the opening
  }

  function nearestLoaded(i) {
    for (let d = 0; d <= LAST; d++) {
      if (frames[i - d]) return i - d;
      if (frames[i + d]) return i + d;
    }
    return -1;
  }

  function schedule() {
    if (queued) return;
    queued = true;
    requestAnimationFrame(render);
  }

  // Redraws only when the frame to show has changed, or the size or settings have.
  function render() {
    queued = false;
    if (!visible) return;
    const i = nearestLoaded(targetFrame());
    if (i < 0 || (i === shown && !dirty)) return;
    shown = i;
    dirty = false;
    draw(i);
  }

  function resize() {
    const dpr = Math.min(devicePixelRatio || 1, 2);
    canvas.width = Math.round(canvas.clientWidth * dpr);
    canvas.height = Math.round(canvas.clientHeight * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.imageSmoothingQuality = 'high';
    dirty = true;
    render(); // draw now: resizing the canvas has just cleared it
  }

  function apply() {
    const isStill = still();
    document.documentElement.classList.toggle('still', isStill);
    hero.style.setProperty('--hero-length', HERO_LENGTH[settings.speed] || HERO_LENGTH.normal);
    if (isStill) load(LAST);
    else loadAll();
    dirty = true;
    schedule();
  }

  // Try-out panel -------------------------------------------------------------------
  // Only on this computer (localhost), so the options can be compared by clicking.

  if (location.hostname === 'localhost' || location.hostname === '127.0.0.1') {
    const OPTIONS = [
      ['size', 'Book size', { sharp: 'Sharp', big: 'Big' }],
      ['phone', 'On phones', { zoom: 'Zoom out', fit: 'Whole book' }],
      ['speed', 'Opening', { slow: 'Slow', normal: 'Normal', quick: 'Quick' }],
      ['motion', 'Animation', { on: 'On', off: 'Off' }],
    ];

    const panel = document.createElement('details');
    panel.className = 'try';
    panel.open = true;
    panel.innerHTML =
      '<summary>Try options <small>(only you see this)</small></summary>' +
      OPTIONS.map(
        ([key, label, choices]) =>
          `<div class="try-row" role="group" aria-label="${label}"><span>${label}</span>` +
          Object.entries(choices)
            .map(([value, text]) => `<button type="button" data-key="${key}" data-value="${value}">${text}</button>`)
            .join('') +
          '</div>',
      ).join('');

    const sync = () => {
      for (const button of panel.querySelectorAll('button')) {
        const { key, value } = button.dataset;
        const current = key === 'motion' ? (still() ? 'off' : 'on') : settings[key];
        button.setAttribute('aria-pressed', String(current === value));
      }
    };

    panel.addEventListener('click', (event) => {
      const button = event.target.closest('button');
      if (!button) return;
      settings[button.dataset.key] = button.dataset.value;
      try {
        localStorage.setItem('hero-try', JSON.stringify(settings));
      } catch {}
      apply();
      sync();
    });

    reduceMotion.addEventListener('change', sync);
    sync();
    document.body.append(panel);
  }

  addEventListener('scroll', schedule, { passive: true });
  reduceMotion.addEventListener('change', apply);
  new ResizeObserver(resize).observe(canvas);
  new IntersectionObserver(([entry]) => {
    visible = entry.isIntersecting;
    dirty = true;
    schedule();
  }).observe(hero);
  apply();
})();

