/* Phase 1: hero scroll animation only. Theme tokens and fonts arrive in phase 2. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

:root {
  --ground: #1F1A18; /* the footage's own background, so the frame's edges disappear */
  color-scheme: dark;
}

html,
body {
  margin: 0;
  background: var(--ground);
}

/* A tall section; the stage inside it stays pinned while it scrolls past. Its height sets
   how much scrolling the opening takes: slower on computers, where a mouse wheel moves in
   big steps, than on phones. */
.hero {
  position: relative;
  height: 550vh;
}

@media (max-width: 767px) {
  .hero {
    height: 400vh;
  }
}

.stage {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh; /* the book stays whole behind mobile browser bars */
  overflow: hidden;
}

.stage canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* Reduced motion: no scrubbing, just the open book. */
.still .hero {
  height: auto;
}

